import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Solid-Item Feedback / Flow Regularization","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"固体反馈/整流","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pBac1odUlClSBZoxZFu995","scope":"page"}},"headers":[],"relativePath":"src/page-pBac1odUlClSBZoxZFu995.md","filePath":"logistics/src/page-pBac1odUlClSBZoxZFu995.md","lastUpdated":null}'),r={name:"src/page-pBac1odUlClSBZoxZFu995.md"};function l(n,e,s,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="固体反馈-整流" aria-hidden="true"></span><h1 id="solid-item-feedback-flow-regularization" tabindex="-1">Solid-Item Feedback / Flow Regularization <a class="header-anchor" href="#solid-item-feedback-flow-regularization" aria-label="Permalink to &quot;Solid-Item Feedback / Flow Regularization&quot;">​</a></h1><blockquote><p>Source page ID: <code>pBac1odUlClSBZoxZFu995</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pBac1odUlClSBZoxZFu995" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Who created this page: kokobird</p><p>Why: to save the solid-item feedback blueprint by 未来科技佬, study it in detail when time permits, and put it in an appropriate location.</p><p><a href="https://beta.enka.network/endfield/aic/?id=w2N2A5u7H2t0w2" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=w2N2A5u7H2t0w2</a></p><p>Principle: powder enters the Protocol Stash first and then forms a loop. Although Xiranite enters the Stash at the end, only the powder earlier in its slot order is output first. Once Xiranite fills the middle section&#39;s buffer, it overflows and merges with the powder. At this point the Stash should be full of powder and Xiranite. After merging, Xiranite waits at the entrance while keeping powder outside. Only half-rate powder remains on the other path, so the amount of powder in the Stash gradually decreases. Eventually Xiranite begins outputting at full rate, until the middle buffer empties.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e388e8752d96a065.q90-3b18762ff61841a8.webp" alt="Solid-Item Feedback / Flow Regularization"></p><p>The solid-item flow regularizer by 全君出击: Originium Powder and Dense Originium Powder on the left form a periodic clock. Originium Powder enters the Originium loop and creates a vacancy there, which Sandleaf Powder fills. Originally the Sandleaf Powder loop contains exactly three items, blocking Carbon output on the right. Once another Sandleaf Powder enters, Carbon outputs at full rate, then closes again.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1673635fa5ddc2f1.q90-f450d54f97905834.webp" alt="Solid-Item Feedback / Flow Regularization"></p></div>',1)])])}const f=t(r,[["render",l]]);export{h as __pageData,f as default};
